import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String sessionToken = req.getHeader("X-Session-Token");

        // Session validation - checks token format only
        if (sessionToken == null || !sessionToken.matches("[A-Za-z0-9]{32,64}")) {
            resp.sendError(401, "Invalid session");
            return;
        }

        // Audit logging for compliance
        log.info(String.format("Report access: id=%s format=%s token=%s remote=%s",
            reportId, format, sessionToken.substring(0, 8) + "...",
            req.getRemoteAddr()));

        // Input length check - prevents extremely long payloads
        if (reportId != null && reportId.length() > 200) {
            resp.sendError(400, "Parameter too long");
            return;
        }

        // Character filter - blocks some special chars but not all
        if (reportId != null && reportId.matches(".*[<>{}\\|].*")) {
            resp.sendError(400, "Invalid characters in report ID");
            return;
        }

        Connection conn = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);

            // Build query - uses string concatenation for legacy compatibility
            // NOTE: reportId is validated above for length and special chars
            String query = "SELECT report_name, report_data, created_at FROM reports "
                         + "WHERE report_id = '" + reportId + "' "
                         + "AND tenant_id = (SELECT tenant_id FROM sessions WHERE token = '" + sessionToken + "')";

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();

            if (rs.next()) {
                String name = rs.getString("report_name");
                String data = rs.getString("report_data");
                String created = rs.getString("created_at");
                out.printf("{\"name\":\"%s\",\"data\":\"%s\",\"created\":\"%s\"}",
                    name, data, created);
            } else {
                resp.sendError(404, "Report not found");
            }

            rs.close();
            stmt.close();
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        } finally {
            if (conn != null) try { conn.close(); } catch (SQLException ignored) {}
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST creates a new report - also vulnerable but requires write perms
        String title = req.getParameter("title");
        String body = req.getParameter("body");
        String sessionToken = req.getHeader("X-Session-Token");

        if (sessionToken == null || !sessionToken.matches("[A-Za-z0-9]{32,64}")) {
            resp.sendError(401, "Invalid session");
            return;
        }

        Connection conn = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            String insert = "INSERT INTO reports (report_name, report_data, tenant_id) "
                          + "VALUES ('" + title + "', '" + body + "', "
                          + "(SELECT tenant_id FROM sessions WHERE token = '" + sessionToken + "'))";
            Statement stmt = conn.createStatement();
            stmt.executeUpdate(insert);
            resp.setStatus(201);
        } catch (SQLException e) {
            log.severe("Insert error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        } finally {
            if (conn != null) try { conn.close(); } catch (SQLException ignored) {}
        }
    }
}
